import { createContext, useContext, useState, useCallback } from "react";
import { MesajProvider, useMesaj } from "./MesajContext";

const Ctx = createContext();

const DEMO_ILANLAR = [
  { id: 1, yuk: "Kömür", nereden: "Antalya", nereye: "İzmir", ton: 22, ucret: 8500, sure: "~7 saat", tarih: "2026-05-06", aracTip: "TIR / Kapalı Kasa", aciklama: "Antalya Liman'dan İzmir OSB'ye kömür. Sabah 08:00 yükleme. Kapalı kasa TIR şart.", istekSayisi: 2, durum: "aktif", olusturan: "Mevlüt Taşımacılık A.Ş.", olusturanPuan: 4.8, belgeler: [], odemeTuru: "pesin", odemeGun: 0 },
  { id: 2, yuk: "Çelik Boru", nereden: "Ankara", nereye: "Bursa", ton: 18, ucret: 6200, sure: "~5 saat", tarih: "2026-05-07", aracTip: "Flatbed / Lowbed", aciklama: "Flatbed veya lowbed TIR gerekli. Vinçli yükleme yapılacak.", istekSayisi: 1, durum: "aktif", olusturan: "Kardeşler Çelik Ltd.", olusturanPuan: 4.6, belgeler: [], odemeTuru: "7-gun", odemeGun: 7 },
  { id: 3, yuk: "Soğutmalı Gıda", nereden: "İstanbul", nereye: "Gaziantep", ton: 15, ucret: 11000, sure: "~12 saat", tarih: "2026-05-08", aracTip: "Frigorifik TIR", aciklama: "+4°C soğutmalı araç zorunlu. ATP belgeli kamyon şart. Gece vardiyası.", istekSayisi: 3, durum: "aktif", olusturan: "Metro Gıda Lojistik", olusturanPuan: 4.9, belgeler: [], odemeTuru: "15-gun", odemeGun: 15 },
  { id: 4, yuk: "Meyve (Portakal)", nereden: "Mersin", nereye: "Ankara", ton: 20, ucret: 7800, sure: "~6 saat", tarih: "2026-05-09", aracTip: "Tenteli TIR", aciklama: "Portakal yükü. Havalandırmalı araç tercih edilir. Erken sabah yükleme.", istekSayisi: 0, durum: "aktif", olusturan: "Akdeniz Tarım A.Ş.", olusturanPuan: 4.7, belgeler: [], odemeTuru: "pesin", odemeGun: 0 },
  { id: 5, yuk: "İnşaat Malzemesi", nereden: "Kocaeli", nereye: "Konya", ton: 25, ucret: 9200, sure: "~4 saat", tarih: "2026-05-10", aracTip: "Damperli TIR", aciklama: "Çakıl ve kum karışık yük. Damperli araç şart. Hafta içi her gün.", istekSayisi: 1, durum: "aktif", olusturan: "Anadolu İnşaat", olusturanPuan: 4.5, belgeler: [], odemeTuru: "30-gun", odemeGun: 30 },
  { id: 6, yuk: "Elektronik Eşya", nereden: "İzmir", nereye: "İstanbul", ton: 8, ucret: 5500, sure: "~6 saat", tarih: "2026-05-11", aracTip: "Kapalı Kasa Kamyon", aciklama: "Hassas elektronik ürünler. Sarsıntısız taşıma şart. Sigorta zorunlu.", istekSayisi: 0, durum: "aktif", olusturan: "Ege Elektronik", olusturanPuan: 4.3, belgeler: [], odemeTuru: "pesin", odemeGun: 0 },
  { id: 7, yuk: "Tekstil", nereden: "Bursa", nereye: "İstanbul", ton: 12, ucret: 4200, sure: "~3 saat", tarih: "2026-05-12", aracTip: "Tenteli TIR", aciklama: "Hazır giyim malı. Su geçirmez kaplama tercih edilir.", istekSayisi: 0, durum: "aktif", olusturan: "Bursa Tekstil A.Ş.", olusturanPuan: 4.6, belgeler: [], odemeTuru: "7-gun", odemeGun: 7 },
];

const DEMO_SEFERLER = [
  { id: 1, yuk: "Kömür Nakliyesi", nereden: "Antalya", nereye: "İzmir", ucret: 8200, tarih: "2026-04-28", plaka: "34 TYK 421", kamyoncu: "Mehmet Yılmaz", olusturan: "Mevlüt Taşımacılık A.Ş.", durum: "tamamlandı", teslimTarihi: "2026-04-28", belgeler: [{ ad: "İrsaliye.pdf", tip: "pdf", yuklenen: "Mehmet" }, { ad: "Makbuz.png", tip: "img", yuklenen: "Mehmet" }], odemeTarihi: null, odemeDurumu: "beklemede" },
  { id: 2, yuk: "Çelik Boru", nereden: "Ankara", nereye: "Bursa", ucret: 6100, tarih: "2026-04-22", plaka: "06 ALK 99", kamyoncu: "Ali Kaya", olusturan: "Kardeşler Çelik Ltd.", durum: "tamamlandı", teslimTarihi: "2026-04-22", belgeler: [{ ad: "CMR.pdf", tip: "pdf", yuklenen: "Ali" }], odemeTarihi: null, odemeDurumu: "beklemede" },
  { id: 3, yuk: "Soğutmalı Gıda", nereden: "İstanbul", nereye: "Gaziantep", ucret: 10500, tarih: "2026-04-15", plaka: "34 HSN 07", kamyoncu: "Hasan Tekin", olusturan: "Metro Gıda Lojistik", durum: "tamamlandı", teslimTarihi: "2026-04-15", belgeler: [], odemeTarihi: "2026-04-22", odemeDurumu: "odendi" },
];

export const AppProvider = ({ children }) => {
  const [oturum, setOturum]         = useState(null);
  const [kullanicilar, setKullanicilar] = useState([]);
  const [ilanlar, setIlanlar]       = useState(DEMO_ILANLAR);
  const [seferler, setSeferler]     = useState(DEMO_SEFERLER);
  const [teklifler, setTeklifler]   = useState([]);

  const mesajContext = useMesaj();
  const [konusmalar, setKonusmalar] = useState([]);

  // KAYIT OL
  const kayitOl = useCallback((bilgiler) => {
    const yeniKullanici = { ...bilgiler, id: Date.now(), kayitTarihi: new Date().toISOString().split("T")[0], puan: 0, durum: "aktif" };
    setKullanicilar(prev => [...prev, yeniKullanici]);
    setOturum(yeniKullanici);
    return yeniKullanici;
  }, []);

  // GİRİŞ YAP
  const girisYap = useCallback((rol, ad) => {
    setOturum({ rol, ad, id: Date.now(), kayitTarihi: new Date().toISOString().split("T")[0] });
  }, []);

  const cikisYap = useCallback(() => setOturum(null), []);

  // İLAN EKLE
  const ilanEkle = useCallback((yeni) => {
    const ilan = {
      ...yeni,
      id: Date.now(),
      istekSayisi: 0,
      durum: "aktif",
      belgeler: [],
      odemeTuru: yeni.odemeTuru || "pesin",
      odemeGun: yeni.odemeGun || 0,
      olusturan: oturum?.firmaAdi || oturum?.ad || "Demo Firma",
      olusturanPuan: 5.0,
    };
    setIlanlar(prev => [ilan, ...prev]);
  }, [oturum]);

  const ilanSil = useCallback((id) => setIlanlar(prev => prev.filter(i => i.id !== id)), []);

  // İLAN AL - Kamyoncu işi seçerse
  const ilanAl = useCallback((ilanId, kamyoncu) => {
    const ilan = ilanlar.find(i => i.id === ilanId);

    if (!ilan) return;

    // İlanı güncelle
    setIlanlar(prev => prev.map(i => {
      if (i.id === ilanId) {
        return { ...i, durum: "alindi", istekSayisi: 0 };
      }
      return i;
    }));

    // Yeni sefer ekle
    const secilenTonaj = kamyoncu.secilenTonaj || ilan.ton;
    const ton = secilenTonaj === "serbest" ? 0 : parseInt(secilenTonaj);

    const yeniSefer = {
      id: Date.now(),
      yuk: ilan.yuk,
      nereden: ilan.nereden,
      nereye: ilan.nereye,
      ucret: ilan.ucret,
      tarih: ilan.tarih,
      sure: ilan.sure,
      ton: ton,
      aracTip: ilan.aracTip,
      ilanId: ilan.id,
      plaka: kamyoncu.plaka || "Belirtilmedi",
      kamyoncu: kamyoncu.ad || kamyoncu,
      olusturan: ilan.olusturan,
      durum: "yolda",
      teslimTarihi: null,
      belgeler: [],
      odemeTarihi: null,
      odemeDurumu: "beklemede",
      odemeTuru: ilan.odemeTuru,
      odemeGun: ilan.odemeGun,
    };
    setSeferler(prev => [yeniSefer, ...prev]);

    // OTOMATİK KONUŞMA OLUŞTUR
    const partnerAd = ilan.olusturan;
    const baslik = `${ilan.yuk} - ${ilan.nereden} → ${ilan.nereye}`;

    mesajContext.konusmaAc({
      partnerId: ilanId,
      partnerAd,
      partnerRol: "issiz",
      isTrucker: true,
      baslik,
      konusmaTuru: "is",
      resim: "https://api.dicebear.com/7.x/initials/svg?seed=" + partnerAd.substring(0, 2).toUpperCase(),
      bg: "linear-gradient(135deg, #667eea 0%, #764ba2 100%)"
    });
  }, [ilanlar, mesajContext]);

  // TEKLİF SİSTEMİ KAPATILDI - YENİ LİSTE
  const teklifEkle = useCallback(() => {}, []);
  const teklifGuncelle = useCallback(() => {}, []);

  // BELGE EKLE (Teslim evrağı yükleme)
  const belgeEkle = useCallback((seferId, belge) => {
    setSeferler(prev => prev.map(s => {
      if (s.id === seferId) {
        return {
          ...s,
          durum: "teslima_bekleniyor",
          belgeler: [...s.belgeler, { ...belge, yuklenen: oturum?.ad || oturum }]
        };
      }
      return s;
    }));
  }, [oturum]);

  // ÖDEME YAP (İşveren)
  const odemeYap = useCallback((seferId) => {
    const sefer = seferler.find(s => s.id === seferId);
    if (sefer && sefer.odemeDurumu === "beklemede") {
      setSeferler(prev => prev.map(s => {
        if (s.id === seferId) {
          const odemeTarihi = new Date().toISOString().split("T")[0];
          return { ...s, odemeTarihi, odemeDurumu: "odendi" };
        }
        return s;
      }));
    }
  }, [seferler]);

  // BAKİYE GÜNCELLE
  const odemeGunleriniKabulEt = useCallback((seferId) => {
    setSeferler(prev => prev.map(s => {
      if (s.id === seferId) {
        const teslimTarihi = new Date(s.tarih);
        teslimTarihi.setDate(teslimTarihi.getDate() + (s.odemeGun || 0));
        return {
          ...s,
          teslimTarihi: teslimTarihi.toISOString().split("T")[0],
          durum: "teslima_bekleniyor"
        };
      }
      return s;
    }));
  }, []);

  const adminKullanicilar = [...kullanicilar,
    { id: 9001, ad: "Mehmet Yılmaz", rol: "kamyoncu", puan: 4.9, durum: "aktif", kayitTarihi: "2024-01-15", plaka: "34 TYK 421", aracTip: "TIR / Kapalı Kasa" },
    { id: 9002, ad: "Metro Gıda Lojistik", rol: "issiz", puan: 4.9, durum: "aktif", kayitTarihi: "2024-02-10" },
  ];

  // KONUŞMA OLUŞTURMA - İşveren tarafı
  const konusmaOluştur = useCallback((params) => {
    mesajContext.konusmaAc(params);
  }, [mesajContext]);

  // İLK MESAJ GÖNDERME - İşveren tarafı
  const ilkMesajiGonder = useCallback((konusmaId, metin) => {
    mesajContext.mesajGonder(konusmaId, metin);
  }, [mesajContext]);

  return (
    <Ctx.Provider value={{
      oturum, kullanicilar: adminKullanicilar, ilanlar, seferler, teklifler, konusmalar,
      kayitOl, girisYap, cikisYap,
      ilanEkle, ilanSil, ilanAl, belgeEkle, odemeYap, odemeGunleriniKabulEt,
      konusmaOluştur, ilkMesajiGonder,
      ...mesajContext,
    }}>
      {children}
    </Ctx.Provider>
  );
};

export const useApp = () => useContext(Ctx);
